/* MATRIX Mini R4 phone controller runtime. Generated by src/build_rc.py from src/rc/ (edit those files). */
(function () {
'use strict';
const PARTS = {
  "core": "//@ th=ส่วนกลาง: ส่งข้อความให้หุ่น กดค้าง และหยุด|en=Core: send messages, hold to repeat, and stop|lo=ສ່ວນກາງ: ສົ່ງຂໍ້ຄວາມໃຫ້ຫຸ່ນຍົນ ກົດຄ້າງ ແລະ ຢຸດ\nconst $ = (css) => document.querySelector(css);\nlet online = false;\n\n//@ th=รวมกำลังล้อซ้าย-ขวาเป็นเลขเดียว: (ซ้าย+100)×1000 + (ขวา+100)|en=Pack left and right wheel power into one number: (L+100)×1000 + (R+100)|lo=ລວມກຳລັງລໍ້ຊ້າຍ-ຂວາເປັນເລກດຽວ: (ຊ້າຍ+100)×1000 + (ຂວາ+100)\n//@ th=เช่น ซ้าย 60 ขวา 40 → \"160140\" · หุ่นรู้ว่าเลขตั้งแต่ 1000 ขึ้นไปคือคันโยก|en=e.g. left 60, right 40 → \"160140\" · the robot knows a number of 1000 or more is the stick|lo=ເຊັ່ນ ຊ້າຍ 60 ຂວາ 40 → \"160140\" · ຫຸ່ນຍົນຮູ້ວ່າເລກຕັ້ງແຕ່ 1000 ຂຶ້ນໄປແມ່ນຄັນໂຍກ\nfunction pack(l, r) {\n  const fit = (v) => Math.max(-99, Math.min(99, Math.round(v)));\n  return String((fit(l) + 100) * 1000 + (fit(r) + 100));\n}\n\n//@ th=คันโยก → กำลังล้อ: y = เดินหน้า/ถอย, x = เลี้ยว (−1 ถึง 1), speed = กำลังสูงสุด|en=Stick → wheel power: y = forward/back, x = turn (−1 to 1), speed = top power|lo=ຄັນໂຍກ → ກຳລັງລໍ້: y = ເດີນໜ້າ/ຖອຍ, x = ລ້ຽວ (−1 ຫາ 1), speed = ກຳລັງສູງສຸດ\nfunction mix(x, y, speed) {\n  const fit = (v, max) => Math.max(-max, Math.min(max, v));\n  return [fit(Math.round(fit(y + x, 1) * speed), 99), fit(Math.round(fit(y - x, 1) * speed), 99)];\n}\n\n//@ th=ส่งข้อความให้หุ่น (ถ้ายังไม่เชื่อมต่อ จะแสดงบนจออย่างเดียว)|en=Send text to the robot (when not connected it is only shown on screen)|lo=ສົ່ງຂໍ້ຄວາມໃຫ້ຫຸ່ນຍົນ (ຖ້າຍັງບໍ່ເຊື່ອມຕໍ່ ຈະສະແດງເທິງຈໍຢ່າງດຽວ)\nfunction send(text) {\n  if (!text) return;\n  log('out', text);\n  if (online) Link.write(text);\n}\n\n//@ th=แสดงข้อความ: out = ส่งไป, in = หุ่นตอบมา, info = แจ้งเตือน|en=Show a message: out = sent, in = from the robot, info = notice|lo=ສະແດງຂໍ້ຄວາມ: out = ສົ່ງໄປ, in = ຫຸ່ນຍົນຕອບມາ, info = ແຈ້ງເຕືອນ\nfunction log(dir, text) {\n  $({ out: '#out', in: '#in', info: '#note' }[dir]).textContent = text;\n  if (typeof termAdd === 'function') termAdd(dir, text);\n}\n\n//@ th=กดค้าง: ส่งซ้ำทุก ms มิลลิวินาที จนกว่าจะเรียก stop() · ปล่อยครบทุกอย่างแล้วส่ง S|en=Hold: send again every ms milliseconds until stop() is called · when nothing is held, send S|lo=ກົດຄ້າງ: ສົ່ງຊ້ຳທຸກ ms ມິນລິວິນາທີ ຈົນກວ່າຈະເອີ້ນ stop() · ປ່ອຍໝົດທຸກຢ່າງແລ້ວສົ່ງ S\nconst repeats = new Set();\nfunction holdRepeat(text, ms) {\n  const get = typeof text === 'function' ? text : () => text;\n  send(get());\n  const timer = setInterval(() => send(get()), ms);\n  function stop() {\n    if (!repeats.delete(stop)) return;\n    clearInterval(timer);\n    if (repeats.size === 0) send('S');\n  }\n  repeats.add(stop);\n  return stop;\n}\n\n//@ th=จำว่านิ้วไหน (pointerId) กดปุ่มไหน จึงใช้หลายนิ้วพร้อมกันได้|en=Remember which finger (pointerId) holds which control, so several fingers work at once|lo=ຈື່ວ່ານິ້ວໃດ (pointerId) ກົດປຸ່ມໃດ ຈຶ່ງໃຊ້ຫຼາຍນິ້ວພ້ອມກັນໄດ້\nconst pressed = new Map();\nfunction press(el, down, up, move) {\n  let finger = null;\n  function end(e) {\n    if (finger === null || (e && e.pointerId !== finger)) return;\n    finger = null;\n    pressed.delete(el);\n    el.classList.remove('held');\n    if (up) up();\n  }\n  el.addEventListener('pointerdown', (e) => {\n    if (finger !== null) return;\n    finger = e.pointerId;\n    el.setPointerCapture(finger);\n    el.classList.add('held');\n    down(e);\n    pressed.set(el, end);\n  });\n  el.addEventListener('pointermove', (e) => {\n    if (move && e.pointerId === finger) move(e);\n  });\n  el.addEventListener('pointerup', end);\n  el.addEventListener('pointercancel', end);\n}\n\n//@ th=ปล่อยทุกปุ่ม (ปิดจอ สลับแอป หรือหลุดการเชื่อมต่อ) · ได้ true ถ้าส่ง S ไปแล้ว|en=Let go of everything (screen off, app switched or connection lost) · true if S was sent|lo=ປ່ອຍທຸກປຸ່ມ (ປິດຈໍ ສະຫຼັບແອັບ ຫຼື ຫຼຸດການເຊື່ອມຕໍ່) · ໄດ້ true ຖ້າສົ່ງ S ແລ້ວ\nfunction releaseAll() {\n  const held = repeats.size > 0;\n  pressed.forEach((end) => end());\n  repeats.forEach((stop) => stop());\n  return held;\n}\n\n//@ th=ปุ่มเชื่อมต่อ และสถานะ (จุดเขียว + ชื่อหุ่น = ต่ออยู่กับหุ่นตัวนั้น)|en=Connect button and status (green dot + robot name = connected to that robot)|lo=ປຸ່ມເຊື່ອມຕໍ່ ແລະ ສະຖານະ (ຈຸດຂຽວ + ຊື່ຫຸ່ນຍົນ = ເຊື່ອມຕໍ່ຢູ່ກັບຫຸ່ນຍົນໂຕນັ້ນ)\n$('#connect').onclick = () => {\n  $('#status').textContent = '{{wait}}';\n  Link.connect().catch((e) => {\n    if (!online) $('#status').textContent = '{{off}}';\n    log('info', '{{fail}}: ' + e.message);\n  });\n};\nLink.onState((state, name) => {\n  const was = online;\n  online = state === 'on';\n  $('#dot').className = state;\n  $('#status').textContent = online ? name : '{{off}}';\n  if (online) {\n    $('#note').textContent = '';\n    //@ th=หลายหุ่นในห้องเดียว: เตือนถ้าต่อกับหุ่นคนละชื่อ|en=Many robots in one room: warn when connected to a robot with another name|lo=ຫຼາຍຫຸ່ນຍົນໃນຫ້ອງດຽວ: ເຕືອນຖ້າເຊື່ອມຕໍ່ກັບຫຸ່ນຍົນຄົນລະຊື່\n    if (name !== CONFIG.name) log('info', '{{other}}: ' + CONFIG.name);\n  } else {\n    releaseAll();\n    if (was) log('info', '{{lost}}');\n  }\n});\nLink.onText((text) => log('in', text));\n\n//@ th=ปิดจอ สลับแอป หรือออกจากหน้า ตอนกดค้าง → ปล่อยทุกปุ่มและส่ง S|en=Screen off, app switched or page left while holding → let go and send S|lo=ປິດຈໍ ສະຫຼັບແອັບ ຫຼື ອອກຈາກໜ້າ ຕອນກົດຄ້າງ → ປ່ອຍທຸກປຸ່ມ ແລະ ສົ່ງ S\ndocument.addEventListener('visibilitychange', () => {\n  if (document.hidden) releaseAll();\n});\naddEventListener('pagehide', releaseAll);\naddEventListener('blur', releaseAll);\n//@ th=กดค้างบนปุ่มแล้วไม่ให้ขึ้นเมนู|en=No pop-up menu on a long press|lo=ກົດຄ້າງເທິງປຸ່ມແລ້ວບໍ່ໃຫ້ຂຶ້ນເມນູ\naddEventListener('contextmenu', (e) => {\n  if (e.target.closest('#pad')) e.preventDefault();\n});\n//@ th=ปุ่มหยุดสีแดง: ปล่อยทุกอย่างแล้วส่ง S|en=Red stop button: let go of everything and send S|lo=ປຸ່ມຢຸດສີແດງ: ປ່ອຍທຸກຢ່າງແລ້ວສົ່ງ S\ndocument.querySelectorAll('.stop').forEach((b) => press(b, () => releaseAll() || send('S')));\n",
  "link_ble": "//@ th=เชื่อมต่อ Bluetooth แบบ UART (บริการเดียวกับที่ MATRIXblock สร้างในหุ่น)|en=Bluetooth UART link (the same service MATRIXblock puts in the robot)|lo=ເຊື່ອມຕໍ່ Bluetooth ແບບ UART (ບໍລິການດຽວກັບທີ່ MATRIXblock ສ້າງໃນຫຸ່ນຍົນ)\nconst UART = '6e400001-b5a3-f393-e0a9-e50e24dcca9e';\nconst TO_ROBOT = '6e400002-b5a3-f393-e0a9-e50e24dcca9e';\nconst FROM_ROBOT = '6e400003-b5a3-f393-e0a9-e50e24dcca9e';\nconst Link = {\n  dev: null, rx: null, tx: null, queue: [], busy: false,\n  textCb() {}, stateCb() {},\n  onText(cb) { this.textCb = cb; },\n  onState(cb) { this.stateCb = cb; },\n  async connect() {\n    if (!navigator.bluetooth) throw new Error('{{noBle}}');\n    //@ th=ครั้งแรก หรือกดตอนต่ออยู่ → เลือกหุ่นจากรายการ · หลุดแล้วกดใหม่ → ต่อหุ่นตัวเดิม|en=First time, or tapped while connected → pick a robot from the list · after a drop → the same robot again|lo=ເທື່ອທຳອິດ ຫຼື ກົດຕອນເຊື່ອມຕໍ່ຢູ່ → ເລືອກຫຸ່ນຍົນຈາກລາຍການ · ຫຼຸດແລ້ວກົດໃໝ່ → ເຊື່ອມຕໍ່ຫຸ່ນຍົນໂຕເດີມ\n    if (!this.dev || this.dev.gatt.connected) {\n      if (this.dev) this.dev.gatt.disconnect();\n      const dev = await navigator.bluetooth.requestDevice({ filters: [{ services: [UART] }] }).catch((e) => {\n        throw e.name === 'SecurityError' ? new Error('{{noBle}}') : e;\n      });\n      dev.addEventListener('gattserverdisconnected', () => {\n        if (dev === this.dev) this.lost();\n      });\n      this.dev = dev;\n    }\n    const uart = await (await this.dev.gatt.connect()).getPrimaryService(UART);\n    this.rx = await uart.getCharacteristic(TO_ROBOT);\n    const tx = await uart.getCharacteristic(FROM_ROBOT);\n    if (tx !== this.tx) tx.addEventListener('characteristicvaluechanged', () => this.textCb(new TextDecoder().decode(tx.value)));\n    this.tx = tx;\n    await tx.startNotifications();\n    this.stateCb('on', this.dev.name);\n  },\n  lost() {\n    this.rx = null;\n    this.queue = [];\n    this.stateCb('off');\n  },\n  //@ th=ส่งทีละข้อความ (Bluetooth ส่งซ้อนกันไม่ได้) · ค่าคันโยกที่รอคิวอยู่ ใช้ค่าล่าสุดแทน|en=One write at a time (Bluetooth cannot overlap writes) · a stick value still waiting is replaced by the newest|lo=ສົ່ງເທື່ອລະຂໍ້ຄວາມ (Bluetooth ສົ່ງຊ້ອນກັນບໍ່ໄດ້) · ຄ່າຄັນໂຍກທີ່ລໍຖ້າຢູ່ ໃຊ້ຄ່າລ່າສຸດແທນ\n  write(text) {\n    const q = this.queue, last = q[q.length - 1], isStick = (t) => Number(t) >= 1000;\n    if (last === text || (isStick(last) && isStick(text))) q[q.length - 1] = text;\n    else q.push(text);\n    if (q.length > 10) q.shift();\n    return this.pump();\n  },\n  async pump() {\n    if (this.busy) return;\n    this.busy = true;\n    while (this.queue.length && this.rx) {\n      const data = new TextEncoder().encode(this.queue.shift());\n      try {\n        if (this.rx.properties.writeWithoutResponse) await this.rx.writeValueWithoutResponse(data);\n        else await this.rx.writeValue(data);\n      } catch (e) {\n        if (this.rx) log('info', e.message);\n      }\n    }\n    this.busy = false;\n  },\n};\n//@ th=เบราว์เซอร์นี้ไม่มี Bluetooth → บอกให้ใช้ Chrome หรือ Bluefy (รอให้สคริปต์ทั้งหน้าทำงานก่อน)|en=No Bluetooth in this browser → say to use Chrome or Bluefy (once the whole script has run)|lo=ບຣາວເຊີນີ້ບໍ່ມີ Bluetooth → ບອກໃຫ້ໃຊ້ Chrome ຫຼື Bluefy (ລໍໃຫ້ສະຄຣິບທັງໜ້າເຮັດວຽກກ່ອນ)\nif (!navigator.bluetooth) setTimeout(() => log('info', '{{noBle}}'));\n",
  "link_mqtt": "//@ th=เชื่อมต่อแบบ MQTT ผ่าน WebSocket: มือถือ → broker → หุ่น|en=MQTT link over WebSocket: phone → broker → robot|lo=ເຊື່ອມຕໍ່ແບບ MQTT ຜ່ານ WebSocket: ມືຖື → broker → ຫຸ່ນຍົນ\n//@ th=คำสั่งไปที่หัวข้อ mr4/<ชื่อหุ่น>/cmd · หุ่นตอบที่ mr4/<ชื่อหุ่น>/msg|en=Commands go to topic mr4/<robot name>/cmd · the robot answers on mr4/<robot name>/msg|lo=ຄຳສັ່ງໄປທີ່ຫົວຂໍ້ mr4/<ຊື່ຫຸ່ນຍົນ>/cmd · ຫຸ່ນຍົນຕອບທີ່ mr4/<ຊື່ຫຸ່ນຍົນ>/msg\nconst MQTT = {\n  //@ th=แพ็กเก็ต = ไบต์ชนิด + ความยาว (ไบต์ละ 7 บิต) + เนื้อหา|en=Packet = type byte + length (7 bits per byte) + body|lo=ແພັກເກັດ = ໄບຕ໌ຊະນິດ + ຄວາມຍາວ (ໄບຕ໌ລະ 7 ບິດ) + ເນື້ອໃນ\n  packet(type, body) {\n    const head = [type];\n    let n = body.length;\n    do {\n      head.push((n % 128) + (n >= 128 ? 128 : 0));\n      n = Math.floor(n / 128);\n    } while (n > 0);\n    return new Uint8Array([...head, ...body]);\n  },\n  //@ th=ข้อความ = ความยาว 2 ไบต์ + ตัวอักษร UTF-8|en=String = 2-byte length + UTF-8 bytes|lo=ຂໍ້ຄວາມ = ຄວາມຍາວ 2 ໄບຕ໌ + ຕົວອັກສອນ UTF-8\n  str(s) {\n    const b = new TextEncoder().encode(s);\n    return [b.length >> 8, b.length & 255, ...b];\n  },\n  //@ th=CONNECT: MQTT 3.1.1 (รุ่น 4), clean session, keepalive เป็นวินาที|en=CONNECT: MQTT 3.1.1 (level 4), clean session, keepalive in seconds|lo=CONNECT: MQTT 3.1.1 (ລຸ້ນ 4), clean session, keepalive ເປັນວິນາທີ\n  connect(id, keepalive) {\n    return this.packet(0x10, [...this.str('MQTT'), 4, 2, keepalive >> 8, keepalive & 255, ...this.str(id)]);\n  },\n  publish(topic, text) {\n    return this.packet(0x30, [...this.str(topic), ...new TextEncoder().encode(text)]);\n  },\n  subscribe(topic) {\n    return this.packet(0x82, [0, 1, ...this.str(topic), 0]);\n  },\n  ping() {\n    return new Uint8Array([0xc0, 0]);\n  },\n  //@ th=อ่านแพ็กเก็ตที่ครบแล้ว 1 อัน (ยังไม่ครบ = null)|en=Read one whole packet (not complete yet = null)|lo=ອ່ານແພັກເກັດທີ່ຄົບແລ້ວ 1 ອັນ (ຍັງບໍ່ຄົບ = null)\n  decode(b) {\n    let len = 0, i = 1;\n    for (let mul = 1; ; mul *= 128) {\n      if (i >= b.length) return null;\n      len += (b[i] & 127) * mul;\n      if (b[i++] < 128) break;\n    }\n    if (b.length < i + len) return null;\n    const p = { type: b[0] >> 4, size: i + len, body: b.slice(i, i + len) };\n    if (p.type === 3) {\n      const n = (p.body[0] << 8) + p.body[1], start = 2 + n + ((b[0] & 6) ? 2 : 0);\n      p.topic = new TextDecoder().decode(p.body.slice(2, 2 + n));\n      p.text = new TextDecoder().decode(p.body.slice(start));\n    }\n    return p;\n  },\n};\nconst Link = {\n  ws: null, textCb() {}, stateCb() {},\n  onText(cb) { this.textCb = cb; },\n  onState(cb) { this.stateCb = cb; },\n  topic(end) { return 'mr4/' + CONFIG.name + '/' + end; },\n  connect() {\n    //@ th=กดซ้ำ → ปิดการเชื่อมต่อเก่า แล้วต่อใหม่|en=Tapped again → close the old connection and start a new one|lo=ກົດຊ້ຳ → ປິດການເຊື່ອມຕໍ່ເກົ່າ ແລ້ວເຊື່ອມຕໍ່ໃໝ່\n    if (this.ws) this.ws.close();\n    return new Promise((ok, fail) => {\n      const ws = new WebSocket(CONFIG.mqtt.url, 'mqtt');\n      let buf = new Uint8Array(0), ping = 0;\n      this.ws = ws;\n      ws.binaryType = 'arraybuffer';\n      ws.onopen = () => ws.send(MQTT.connect('rc-' + Math.random().toString(36).slice(2, 8), 30));\n      ws.onerror = () => fail(new Error(CONFIG.mqtt.url));\n      ws.onclose = () => {\n        clearInterval(ping);\n        if (this.ws !== ws) return;\n        this.ws = null;\n        this.stateCb('off');\n      };\n      ws.onmessage = (e) => {\n        buf = new Uint8Array([...buf, ...new Uint8Array(e.data)]);\n        for (let p; (p = MQTT.decode(buf)); buf = buf.slice(p.size)) {\n          if (p.type === 2 && p.body[1] !== 0) {\n            fail(new Error('CONNACK ' + p.body[1]));\n            ws.close();\n          } else if (p.type === 2) {\n            ws.send(MQTT.subscribe(this.topic('msg')));\n            //@ th=ส่ง PINGREQ ทุก 15 วินาที (ครึ่งหนึ่งของ keepalive) ให้ broker รู้ว่ายังอยู่|en=PINGREQ every 15 s (half the keepalive) so the broker knows we are still here|lo=ສົ່ງ PINGREQ ທຸກ 15 ວິນາທີ (ເຄິ່ງໜຶ່ງຂອງ keepalive) ໃຫ້ broker ຮູ້ວ່າຍັງຢູ່\n            ping = setInterval(() => ws.send(MQTT.ping()), 15000);\n            this.stateCb('on', CONFIG.name);\n            ok();\n          } else if (p.type === 9 && p.body[2] === 0x80) log('info', '{{fail}}: ' + this.topic('msg'));\n          else if (p.type === 3) this.textCb(p.text);\n        }\n      };\n    });\n  },\n  async write(text) {\n    if (this.ws && this.ws.readyState === WebSocket.OPEN) this.ws.send(MQTT.publish(this.topic('cmd'), text));\n  },\n};\n",
  "mode_buttons": "//@ th=ปุ่ม 4 ทิศ: data-cmd คือข้อความที่ส่ง (F เดินหน้า, B ถอย, L เลี้ยวซ้าย, R เลี้ยวขวา)|en=4 direction buttons: data-cmd is the text sent (F forward, B back, L left, R right)|lo=ປຸ່ມ 4 ທິດ: data-cmd ແມ່ນຂໍ້ຄວາມທີ່ສົ່ງ (F ເດີນໜ້າ, B ຖອຍ, L ລ້ຽວຊ້າຍ, R ລ້ຽວຂວາ)\n//@ th=tap4 = กด 1 ครั้ง ส่ง 1 ครั้ง · hold4 = กดค้างส่งซ้ำทุก 0.15 วินาที ปล่อยแล้วส่ง S|en=tap4 = one tap sends once · hold4 = holding sends again every 0.15 s, letting go sends S|lo=tap4 = ກົດ 1 ເທື່ອ ສົ່ງ 1 ເທື່ອ · hold4 = ກົດຄ້າງສົ່ງຊ້ຳທຸກ 0.15 ວິນາທີ ປ່ອຍແລ້ວສົ່ງ S\ndocument.querySelectorAll('[data-cmd]').forEach((b) => {\n  const cmd = b.dataset.cmd;\n  if (CONFIG.mode === 'tap4') press(b, () => send(cmd));\n  else {\n    let stop = null;\n    press(b, () => { stop = holdRepeat(cmd, 150); }, () => stop());\n  }\n});\n",
  "mode_stick": "//@ th=คันโยก: ลากปุ่มกลมสีขาว · ส่งกำลังล้อเป็นเลขเดียวทุก 0.1 วินาที · ปล่อยครบแล้วส่ง S|en=Sticks: drag the white knob · wheel power is sent as one number every 0.1 s · letting go sends S|lo=ຄັນໂຍກ: ລາກປຸ່ມກົມສີຂາວ · ສົ່ງກຳລັງລໍ້ເປັນເລກດຽວທຸກ 0.1 ວິນາທີ · ປ່ອຍໝົດແລ້ວສົ່ງ S\n//@ th=data-axis: xy = คันโยกเดียว, y = เดินหน้า/ถอย, x = เลี้ยว|en=data-axis: xy = one stick, y = forward/back, x = turn|lo=data-axis: xy = ຄັນໂຍກດຽວ, y = ເດີນໜ້າ/ຖອຍ, x = ລ້ຽວ\nconst joy = { x: 0, y: 0, held: 0, stop: null };\ndocument.querySelectorAll('.stick').forEach((track) => {\n  const knob = track.querySelector('b'), axis = track.dataset.axis;\n  function drag(e) {\n    const r = track.getBoundingClientRect();\n    const rx = (r.width - knob.offsetWidth) / 2, ry = (r.height - knob.offsetHeight) / 2;\n    let x = axis === 'y' ? 0 : (e.clientX - r.left - r.width / 2) / rx;\n    let y = axis === 'x' ? 0 : (e.clientY - r.top - r.height / 2) / ry;\n    const len = Math.hypot(x, y);\n    if (len > 1) { x /= len; y /= len; }\n    knob.style.transform = `translate(${x * rx}px, ${y * ry}px)`;\n    //@ th=บนจอ y เพิ่มเมื่อลงล่าง แต่ดันขึ้น = เดินหน้า จึงกลับเครื่องหมาย|en=On screen y grows downward, but pushing up = forward, so flip the sign|lo=ເທິງຈໍ y ເພີ່ມເມື່ອລົງລຸ່ມ ແຕ່ດັນຂຶ້ນ = ເດີນໜ້າ ຈຶ່ງປີ້ນເຄື່ອງໝາຍ\n    if (axis !== 'y') joy.x = x;\n    if (axis !== 'x') joy.y = -y;\n  }\n  press(track, (e) => {\n    drag(e);\n    if (joy.held++ === 0) joy.stop = holdRepeat(() => pack(...mix(joy.x, joy.y, CONFIG.speed)), 100);\n  }, () => {\n    knob.style.transform = '';\n    if (axis !== 'y') joy.x = 0;\n    if (axis !== 'x') joy.y = 0;\n    if (--joy.held === 0) joy.stop();\n  }, drag);\n});\n",
  "extra_buttons": "//@ th=ปุ่มพิเศษ: กดแล้วส่ง data-press · ปล่อยแล้วส่ง data-release (ว่าง = ไม่ส่ง)|en=Extra buttons: pressing sends data-press · letting go sends data-release (empty = nothing)|lo=ປຸ່ມພິເສດ: ກົດແລ້ວສົ່ງ data-press · ປ່ອຍແລ້ວສົ່ງ data-release (ວ່າງ = ບໍ່ສົ່ງ)\ndocument.querySelectorAll('.xbtn').forEach((b) => {\n  press(b, () => send(b.dataset.press), () => send(b.dataset.release));\n});\n",
  "terminal": "//@ th=หน้าต่างข้อความ: พิมพ์แล้วกดส่ง · ข้อความที่หุ่นตอบจะขึ้นตรงนี้|en=Terminal: type and send · the robot's answers show here|lo=ໜ້າຕ່າງຂໍ້ຄວາມ: ພິມແລ້ວກົດສົ່ງ · ຂໍ້ຄວາມທີ່ຫຸ່ນຍົນຕອບຈະຂຶ້ນຢູ່ນີ້\nfunction termAdd(dir, text) {\n  const box = $('#log'), last = box.lastElementChild;\n  if (!text) return;\n  //@ th=ข้อความเดิมซ้ำ → นับจำนวน ไม่ขึ้นบรรทัดใหม่|en=The same message again → count it instead of adding a line|lo=ຂໍ້ຄວາມເດີມຊ້ຳ → ນັບຈຳນວນ ບໍ່ຂຶ້ນແຖວໃໝ່\n  if (last && last.className === dir && last.dataset.text === text) {\n    last.dataset.n = Number(last.dataset.n) + 1;\n    last.textContent = text + '  ×' + last.dataset.n;\n    return;\n  }\n  const line = document.createElement('div');\n  line.className = dir;\n  line.dataset.text = text;\n  line.dataset.n = 1;\n  line.textContent = text;\n  box.append(line);\n  if (box.children.length > 100) box.firstElementChild.remove();\n  box.scrollTop = box.scrollHeight;\n}\n$('#sendForm').addEventListener('submit', (e) => {\n  e.preventDefault();\n  send($('#msg').value);\n  $('#msg').value = '';\n});\n"
};
const CSS = "/*== base ==*/\n/*@ th=ทั้งหน้า: พื้นม่วงอ่อนลายจุด เต็มจอ ใช้ฟอนต์ของเครื่อง|en=Whole page: lavender dotted background, full screen, the phone's own font|lo=ທັງໜ້າ: ພື້ນສີມ່ວງອ່ອນລາຍຈຸດ ເຕັມຈໍ ໃຊ້ຟອນຂອງເຄື່ອງ */\n* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }\nhtml, body { margin: 0; height: 100%; }\nbody {\n  display: flex; flex-direction: column; height: 100dvh; overflow: hidden; box-sizing: border-box;\n  padding: 0 env(safe-area-inset-right) env(safe-area-inset-bottom) env(safe-area-inset-left);\n  font: 15px system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif; color: #3B3256;\n  background: #ECE8F7 radial-gradient(#cec5e8 1.5px, transparent 1.7px) 0 0 / 22px 22px;\n}\nbutton { font: inherit; border: 0; cursor: pointer; }\n/*@ th=แถบบน: ปุ่มเชื่อมต่อ จุดสถานะ และข้อความล่าสุด (↑ ส่ง ↓ รับ)|en=Top bar: connect button, status dot and last messages (↑ sent ↓ received)|lo=ແຖບເທິງ: ປຸ່ມເຊື່ອມຕໍ່ ຈຸດສະຖານະ ແລະ ຂໍ້ຄວາມລ່າສຸດ (↑ ສົ່ງ ↓ ຮັບ) */\n#bar { display: flex; align-items: center; gap: 8px; padding: max(8px, env(safe-area-inset-top)) 12px 8px; }\n#connect { flex: none; padding: 8px 16px; border-radius: 99px; background: #3B3256; color: #fff; font-weight: 600; }\n#dot { flex: none; width: 12px; height: 12px; border-radius: 50%; background: #c9c1df; }\n#dot.on { background: #35b37e; }\n#dot.off { background: #EE6B5E; }\n#status { flex: 1; min-width: 0; font-size: 14px; line-height: 1.2; }\n#dot.on + #status { font-weight: 700; }\n#out, #in { max-width: 7em; padding: 3px 8px; border-radius: 8px; background: #fff; font: 13px ui-monospace, monospace; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n#out::before { content: \"↑ \"; color: #7A5CD6; }\n#in::before { content: \"↓ \"; color: #22875a; }\n#out:empty, #in:empty, #note:empty { display: none; }\n#note { margin: 0 12px 8px; padding: 8px 12px; border-left: 4px solid #EE6B5E; border-radius: 10px; background: #fff; font-size: 14px; }\n#main { flex: 1; min-height: 0; display: flex; flex-direction: column; }\n@media (orientation: landscape) { #main { flex-direction: row; } }\n/*@ th=พื้นที่ปุ่ม: ไม่เลื่อนจอ ไม่ซูม ไม่เลือกข้อความ ไม่ขึ้นเมนูเมื่อกดค้าง|en=Control area: no scrolling, zooming, text selection or long-press menu|lo=ພື້ນທີ່ປຸ່ມ: ບໍ່ເລື່ອນຈໍ ບໍ່ຊູມ ບໍ່ເລືອກຂໍ້ຄວາມ ບໍ່ຂຶ້ນເມນູເມື່ອກົດຄ້າງ */\n#pad { flex: 1; position: relative; container-type: size; display: flex; align-items: center; justify-content: center; }\n#pad, #pad * { touch-action: none; user-select: none; -webkit-user-select: none; -webkit-touch-callout: none; }\n.stop { flex: none; width: 76px; height: 76px; border-radius: 50%; background: #EE6B5E; color: #fff; font-weight: 700; box-shadow: 0 6px 16px #EE6B5E66; }\n.stop.held { scale: .93; filter: brightness(1.1); }\n\n/*== round ==*/\n/*@ th=ปุ่มกลมสีเข้ม ลูกศรสามเหลี่ยมสีม่วงอ่อน (หมุนได้ด้วย rotate)|en=Dark round button with a lavender triangle (turn it with rotate)|lo=ປຸ່ມກົມສີເຂັ້ມ ລູກສອນສາມຫຼ່ຽມສີມ່ວງອ່ອນ (ໝຸນໄດ້ດ້ວຍ rotate) */\n.dark { width: 72px; height: 72px; padding: 0; border-radius: 50%; background: #3B3256; box-shadow: 0 6px 16px #3B325655; }\n.dark i { display: block; width: 28px; height: 24px; margin: auto; background: #B7A4EC; clip-path: polygon(50% 0, 100% 100%, 0 100%); }\n.dark.held { scale: .93; background: #54487a; }\n\n/*== dirs ==*/\n/*@ th=วางปุ่ม 4 ทิศเป็นรูปกากบาท ปุ่มหยุดตรงกลาง|en=Lay the 4 buttons out as a cross with stop in the middle|lo=ວາງປຸ່ມ 4 ທິດເປັນຮູບກາກບາດ ປຸ່ມຢຸດຢູ່ກາງ */\n.dirs { display: grid; grid-template-areas: \". up .\" \"left stop right\" \". down .\"; gap: 14px; place-items: center; }\n.dirs .dark, .dirs .stop { width: 84px; height: 84px; }\n.up { grid-area: up; }\n.left { grid-area: left; }\n.dirs .stop { grid-area: stop; }\n.right { grid-area: right; }\n.down { grid-area: down; }\n\n/*== stick ==*/\n/*@ th=คันโยก: รางสีขาว เส้นกากบาทบาง ๆ ปุ่มกลมสีขาวมีจุดม่วงตรงกลาง|en=Sticks: white track, thin crosshair, white knob with a lavender centre dot|lo=ຄັນໂຍກ: ຮາງສີຂາວ ເສັ້ນກາກບາດບາງໆ ປຸ່ມກົມສີຂາວມີຈຸດມ່ວງຢູ່ກາງ */\n/*@ th=cqw/cqh = % ของพื้นที่ปุ่ม (ค่าแรกใช้กับเบราว์เซอร์รุ่นเก่า)|en=cqw/cqh = % of the control area (the first value is for older browsers)|lo=cqw/cqh = % ຂອງພື້ນທີ່ປຸ່ມ (ຄ່າທຳອິດໃຊ້ກັບບຣາວເຊີລຸ້ນເກົ່າ) */\n.ctl { width: 100%; height: 100%; display: flex; align-items: center; justify-content: space-evenly; }\n#pad.x .ctl { padding-right: 22%; }\n.stick { position: relative; flex: none; display: grid; place-items: center; background: #fff; box-shadow: 0 8px 24px #3B325626; }\n.stick::before, .stick::after { content: \"\"; position: absolute; background: #e4ddf4; }\n.stick::before { left: 50%; top: 14%; bottom: 14%; width: 2px; margin-left: -1px; }\n.stick::after { top: 50%; left: 14%; right: 14%; height: 2px; margin-top: -1px; }\n.stick b { position: relative; z-index: 1; width: 66px; height: 66px; border-radius: 50%; background: #fff radial-gradient(#B7A4EC 0 10px, transparent 11px); box-shadow: 0 4px 14px #3B325655; transition: transform .15s; }\n.stick.held b { transition: none; }\n.round { width: 260px; width: min(80cqh, 70cqw, 320px); aspect-ratio: 1; border-radius: 50%; }\n.tall { width: 100px; height: 240px; height: min(84cqh, 300px); border-radius: 50px; }\n.wide { width: 220px; width: min(40cqw, 300px); height: 100px; border-radius: 50px; }\n@media (orientation: portrait) {\n  .ctl { flex-direction: column; }\n  .tall { height: min(42cqh, 280px); }\n  .wide { width: min(64cqw, 300px); }\n}\n\n/*== xbtn ==*/\n/*@ th=ปุ่มพิเศษ: ตำแหน่ง left/top เป็น % ของพื้นที่ปุ่ม ชื่ออยู่ใต้ปุ่ม|en=Extra buttons: left/top are % of the control area, the label sits under the button|lo=ປຸ່ມພິເສດ: ຕຳແໜ່ງ left/top ເປັນ % ຂອງພື້ນທີ່ປຸ່ມ ຊື່ຢູ່ລຸ່ມປຸ່ມ */\n.xbtn { position: absolute; z-index: 2; translate: -50% -50%; }\n.xbtn span { position: absolute; top: 100%; left: 50%; translate: -50% 6px; font-size: 13px; font-weight: 600; color: #3B3256; white-space: nowrap; }\n\n/*== term ==*/\n/*@ th=หน้าต่างข้อความ: ↑ ส่งไป ↓ หุ่นตอบมา|en=Terminal: ↑ sent ↓ from the robot|lo=ໜ້າຕ່າງຂໍ້ຄວາມ: ↑ ສົ່ງໄປ ↓ ຫຸ່ນຍົນຕອບມາ */\n#term { flex: 0 0 34%; min-width: 0; min-height: 0; display: flex; flex-direction: column; margin: 0 10px 10px; border-radius: 16px; background: #fff; box-shadow: 0 6px 18px #3B32561f; }\n#term:only-child { flex: 1; }\n@media (orientation: landscape) { #pad + #term { margin-left: 0; } }\n#log { flex: 1; overflow-y: auto; padding: 10px 14px; font: 14px/1.5 ui-monospace, monospace; overflow-wrap: anywhere; }\n#log .out { color: #7A5CD6; }\n#log .in { color: #22875a; }\n#log .info { color: #c0483c; }\n#log .out::before { content: \"↑ \"; }\n#log .in::before { content: \"↓ \"; }\n#sendForm { display: flex; gap: 8px; padding: 8px; border-top: 1px solid #eee9f8; }\n#msg { flex: 1; min-width: 0; padding: 9px 14px; border: 1px solid #d9d1ef; border-radius: 99px; font: 16px system-ui, sans-serif; }\n#sendForm button { padding: 9px 18px; border-radius: 99px; background: #3B3256; color: #fff; font-weight: 600; }\n";
const TEMPLATE = "<!--== page ==-->\n<!DOCTYPE html>\n<!--@ th=จอยบังคับหุ่น MATRIX Mini R4 · ไฟล์เดียวจบ แก้ได้ทุกบรรทัด|en=MATRIX Mini R4 robot controller · one file, change any line you like|lo=ຈອຍຄວບຄຸມຫຸ່ນຍົນ MATRIX Mini R4 · ໄຟລ໌ດຽວຈົບ ແກ້ໄດ້ທຸກແຖວ -->\n<html lang=\"[[lang]]\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<link rel=\"icon\" href=\"data:,\">\n<title>[[name]] · {{title}}<\/title>\n<style>\n[[css]]\n<\/style>\n<\/head>\n<body>\n<!--@ th=แถบบน: ปุ่มเชื่อมต่อ สถานะ และข้อความล่าสุด|en=Top bar: connect button, status and last messages|lo=ແຖບເທິງ: ປຸ່ມເຊື່ອມຕໍ່ ສະຖານະ ແລະ ຂໍ້ຄວາມລ່າສຸດ -->\n<header id=\"bar\">\n  <button id=\"connect\">{{connect}}<\/button>\n  <i id=\"dot\"><\/i>\n  <span id=\"status\">{{off}}<\/span>\n  <code id=\"out\"><\/code>\n  <code id=\"in\"><\/code>\n<\/header>\n<p id=\"note\"><\/p>\n<div id=\"main\">\n[[pad]]\n[[term]]\n<\/div>\n<script>\n[[js]]\n<\/script>\n<\/body>\n<\/html>\n<!--== pad ==-->\n<main id=\"pad\"[[x]]>\n[[ctl]]\n[[xbtns]]\n<\/main>\n<!--== dirs ==-->\n  <!--@ th=ปุ่ม 4 ทิศ: เปลี่ยน data-cmd เพื่อส่งข้อความอื่น|en=4 direction buttons: change data-cmd to send other text|lo=ປຸ່ມ 4 ທິດ: ປ່ຽນ data-cmd ເພື່ອສົ່ງຂໍ້ຄວາມອື່ນ -->\n  <div class=\"dirs\">\n    <button class=\"dark up\" data-cmd=\"F\"><i style=\"transform:rotate(0deg)\"><\/i><\/button>\n    <button class=\"dark left\" data-cmd=\"L\"><i style=\"transform:rotate(270deg)\"><\/i><\/button>\n    <button class=\"stop\">{{stop}}<\/button>\n    <button class=\"dark right\" data-cmd=\"R\"><i style=\"transform:rotate(90deg)\"><\/i><\/button>\n    <button class=\"dark down\" data-cmd=\"B\"><i style=\"transform:rotate(180deg)\"><\/i><\/button>\n  <\/div>\n<!--== stick1 ==-->\n  <!--@ th=คันโยกเดียว: ดันขึ้น = เดินหน้า ดันไปข้าง = เลี้ยว|en=One stick: push up = forward, push sideways = turn|lo=ຄັນໂຍກດຽວ: ດັນຂຶ້ນ = ເດີນໜ້າ ດັນໄປຂ້າງ = ລ້ຽວ -->\n  <div class=\"ctl\">\n    <div class=\"stick round\" data-axis=\"xy\"><b><\/b><\/div>\n    <button class=\"stop\">{{stop}}<\/button>\n  <\/div>\n<!--== stick2 ==-->\n  <!--@ th=สองคันโยก: ซ้าย = เดินหน้า/ถอย ขวา = เลี้ยว|en=Two sticks: left = forward/back, right = turn|lo=ສອງຄັນໂຍກ: ຊ້າຍ = ເດີນໜ້າ/ຖອຍ ຂວາ = ລ້ຽວ -->\n  <div class=\"ctl\">\n    <div class=\"stick tall\" data-axis=\"y\"><b><\/b><\/div>\n    <button class=\"stop\">{{stop}}<\/button>\n    <div class=\"stick wide\" data-axis=\"x\"><b><\/b><\/div>\n  <\/div>\n<!--== xbtns ==-->\n  <!--@ th=ปุ่มพิเศษ: left/top = ตำแหน่ง (%) · data-press = ส่งตอนกด · data-release = ส่งตอนปล่อย · rotate = หมุนลูกศร|en=Extra buttons: left/top = position (%) · data-press = sent on press · data-release = sent on release · rotate = turns the arrow|lo=ປຸ່ມພິເສດ: left/top = ຕຳແໜ່ງ (%) · data-press = ສົ່ງຕອນກົດ · data-release = ສົ່ງຕອນປ່ອຍ · rotate = ໝຸນລູກສອນ -->\n[[list]]\n<!--== xbtn ==-->\n  <button class=\"dark xbtn\" style=\"left:[[x]]%;top:[[y]]%\" data-press=\"[[press]]\" data-release=\"[[release]]\"><i style=\"transform:rotate([[angle]]deg)\"><\/i><span>[[label]]<\/span><\/button>\n<!--== term ==-->\n<!--@ th=หน้าต่างข้อความ: ดูข้อความที่ส่งและรับ พิมพ์ส่งเองได้|en=Terminal: see what is sent and received, and type your own|lo=ໜ້າຕ່າງຂໍ້ຄວາມ: ເບິ່ງຂໍ້ຄວາມທີ່ສົ່ງ ແລະ ຮັບ ພິມສົ່ງເອງໄດ້ -->\n<section id=\"term\">\n  <div id=\"log\"><\/div>\n  <form id=\"sendForm\"><input id=\"msg\" placeholder=\"{{typeHere}}\" autocomplete=\"off\"><button>{{send}}<\/button><\/form>\n<\/section>\n";
const PRESETS = {"hello": {"name": "R4-T01", "link": "ble", "mqtt": {"url": "wss://broker.hivemq.com:8884/mqtt"}, "mode": "none", "speed": 60, "terminal": true, "buttons": []}, "tap4": {"name": "R4-T01", "link": "ble", "mqtt": {"url": "wss://broker.hivemq.com:8884/mqtt"}, "mode": "tap4", "speed": 60, "terminal": false, "buttons": []}, "hold4": {"name": "R4-T01", "link": "ble", "mqtt": {"url": "wss://broker.hivemq.com:8884/mqtt"}, "mode": "hold4", "speed": 60, "terminal": false, "buttons": []}, "stick1": {"name": "R4-T01", "link": "ble", "mqtt": {"url": "wss://broker.hivemq.com:8884/mqtt"}, "mode": "stick1", "speed": 60, "terminal": false, "buttons": []}, "stick2arm": {"name": "R4-T01", "link": "ble", "mqtt": {"url": "wss://broker.hivemq.com:8884/mqtt"}, "mode": "stick2", "speed": 60, "terminal": false, "buttons": [{"label": {"th": "แขนขึ้น", "en": "Arm up", "lo": "ແຂນຂຶ້ນ"}, "press": "U", "release": "", "angle": 0, "x": 88, "y": 30}, {"label": {"th": "แขนลง", "en": "Arm down", "lo": "ແຂນລົງ"}, "press": "D", "release": "", "angle": 180, "x": 88, "y": 70}]}, "mqtt-hello": {"name": "R4-T01", "link": "mqtt", "mqtt": {"url": "wss://broker.hivemq.com:8884/mqtt"}, "mode": "none", "speed": 60, "terminal": true, "buttons": []}, "mqtt-drive": {"name": "R4-T01", "link": "mqtt", "mqtt": {"url": "wss://broker.hivemq.com:8884/mqtt"}, "mode": "stick2", "speed": 60, "terminal": false, "buttons": [{"label": {"th": "แขนขึ้น", "en": "Arm up", "lo": "ແຂນຂຶ້ນ"}, "press": "U", "release": "", "angle": 0, "x": 88, "y": 30}, {"label": {"th": "แขนลง", "en": "Arm down", "lo": "ແຂນລົງ"}, "press": "D", "release": "", "angle": 180, "x": 88, "y": 70}]}};
// exportHTML(config, lang) -> one standalone controller HTML file (string).
// build_rc.py wraps this file with PARTS (src/rc/parts/*.js by name), CSS (parts/style.css),
// TEMPLATE (export_template.html) and PRESETS (presets.json) into out/web/rc/rc.js.
// Only the parts a config needs go into the file. Source comments are written
// `//@ th=…|en=…|lo=…` (CSS `/*@ … */`, HTML `<!--@ … -->`) and come out as a plain comment
// in the chosen language; `{{key}}` is a UI text from TEXT; `[[slot]]` is filled here.
// Sections of CSS and TEMPLATE start with a line `/*== name ==*/` or `<!--== name ==-->`.

const BROKER = 'wss://broker.hivemq.com:8884/mqtt';
const MODES = ['none', 'tap4', 'hold4', 'stick1', 'stick2'];
const TEXT = {
  th: {
    title: 'จอยบังคับหุ่น', connect: 'เชื่อมต่อ', wait: 'กำลังเชื่อมต่อ…', off: 'ยังไม่เชื่อมต่อ',
    lost: 'หลุดการเชื่อมต่อ กด “เชื่อมต่อ” อีกครั้ง', fail: 'เชื่อมต่อไม่สำเร็จ', stop: 'หยุด', send: 'ส่ง',
    typeHere: 'พิมพ์ข้อความ', other: 'หุ่นตัวนี้ไม่ใช่ชื่อที่ตั้งไว้ใน CONFIG.name',
    noBle: 'เบราว์เซอร์นี้ใช้ Bluetooth ไม่ได้ · Android ใช้ Chrome · iPhone/iPad ใช้แอป Bluefy',
  },
  en: {
    title: 'Robot controller', connect: 'Connect', wait: 'Connecting…', off: 'Not connected',
    lost: 'Connection lost. Tap Connect again.', fail: 'Could not connect', stop: 'STOP', send: 'Send',
    typeHere: 'Type a message', other: 'This robot is not the name set in CONFIG.name',
    noBle: 'This browser has no Web Bluetooth. Android: use Chrome. iPhone/iPad: use the Bluefy app.',
  },
  lo: {
    title: 'ຈອຍຄວບຄຸມຫຸ່ນຍົນ', connect: 'ເຊື່ອມຕໍ່', wait: 'ກຳລັງເຊື່ອມຕໍ່…', off: 'ຍັງບໍ່ໄດ້ເຊື່ອມຕໍ່',
    lost: 'ການເຊື່ອມຕໍ່ຫຼຸດ ກົດ “ເຊື່ອມຕໍ່” ອີກຄັ້ງ', fail: 'ເຊື່ອມຕໍ່ບໍ່ສຳເລັດ', stop: 'ຢຸດ', send: 'ສົ່ງ',
    typeHere: 'ພິມຂໍ້ຄວາມ', other: 'ຫຸ່ນຍົນໂຕນີ້ບໍ່ແມ່ນຊື່ທີ່ຕັ້ງໄວ້ໃນ CONFIG.name',
    noBle: 'ບຣາວເຊີນີ້ໃຊ້ Bluetooth ບໍ່ໄດ້ · Android ໃຊ້ Chrome · iPhone/iPad ໃຊ້ແອັບ Bluefy',
  },
};

const NOTE = /(\/\/|\/\*|<!--)@ th=([^|\n]*)\|en=([^|\n]*)\|lo=(.*?)( \*\/| -->)?$/gm;
const escHTML = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);
const escJS = (s) => s.replace(/[\\']/g, '\\$&');

function localize(src, lang, esc) {
  return src
    .replace(NOTE, (m, open, th, en, lo, close) => open + ' ' + { th, en, lo }[lang].trim() + (close || ''))
    .replace(/\{\{(\w+)\}\}/g, (m, key) => {
      if (!(key in TEXT[lang])) throw new Error('rc: no text for {{' + key + '}}');
      return esc(TEXT[lang][key]);
    });
}

function sections(src) {
  const bits = src.split(/^(?:<!--|\/\*)== (\w+) ==(?:-->|\*\/)\n/m), out = {};
  for (let i = 1; i < bits.length; i += 2) out[bits[i]] = bits[i + 1];
  return out;
}

// [[slot]] alone on a line takes the whole line (removed when empty); other [[slot]]s are inline.
// One pass, so text put into a slot (a button label, say) is never read as a slot itself.
function fill(tpl, slots) {
  const get = (k) => {
    if (!(k in slots)) throw new Error('rc: no slot [[' + k + ']]');
    return String(slots[k]);
  };
  return tpl.replace(/^\[\[(\w+)\]\]\n|\[\[(\w+)\]\]/gm, (m, line, inline) =>
    line ? (get(line) ? get(line).replace(/\n*$/, '\n') : '') : get(inline));
}

function normalize(cfg, lang) {
  const num = (v, lo, hi, d) => Math.min(hi, Math.max(lo, Number.isFinite(Number(v)) && v !== null && v !== '' ? Number(v) : d));
  return {
    name: String(cfg.name || 'R4-T01'),
    link: cfg.link === 'mqtt' ? 'mqtt' : 'ble',
    mqtt: { url: String((cfg.mqtt && cfg.mqtt.url) || BROKER) },
    mode: MODES.includes(cfg.mode) ? cfg.mode : 'none',
    speed: Math.round(num(cfg.speed, 10, 100, 60)),
    terminal: Boolean(cfg.terminal),
    buttons: (cfg.buttons || []).map((b) => ({
      label: b.label && typeof b.label === 'object' ? String(b.label[lang] || b.label.en || '') : String(b.label || ''),
      press: String(b.press || ''),
      release: String(b.release || ''),
      angle: Math.round(num(b.angle, 0, 315, 0)),
      x: Math.round(num(b.x, 0, 100, 50) * 10) / 10,
      y: Math.round(num(b.y, 0, 100, 50) * 10) / 10,
    })),
  };
}

// Comments are localized before the values go in, so a name like "R4-{{x}}" stays as typed.
function configJS(c, dirs, sticks, lang) {
  const q = (v) => JSON.stringify(v).replace(/</g, '\\u003c');
  const say = (note) => localize(note, lang, escJS);
  return [
    say('//@ th=ตั้งค่า (แก้ตรงนี้ได้)|en=Settings (change them here)|lo=ຕັ້ງຄ່າ (ແກ້ບ່ອນນີ້ໄດ້)'),
    'const CONFIG = {',
    `  name: ${q(c.name)}, ` + say('//@ th=ชื่อหุ่น ต้องตรงกับในโค้ดหุ่น|en=robot name, must match the robot code|lo=ຊື່ຫຸ່ນຍົນ ຕ້ອງກົງກັບໃນໂຄດຫຸ່ນຍົນ'),
    c.link === 'mqtt' && `  mqtt: { url: ${q(c.mqtt.url)} }, ` + say('//@ th=broker (มือถือใช้ wss)|en=broker (phones use wss)|lo=broker (ມືຖືໃຊ້ wss)'),
    dirs && `  mode: ${q(c.mode)}, ` + say('//@ th=tap4 = กดครั้งเดียว · hold4 = กดค้าง|en=tap4 = tap once · hold4 = hold down|lo=tap4 = ກົດເທື່ອດຽວ · hold4 = ກົດຄ້າງ'),
    sticks && `  speed: ${c.speed}, ` + say('//@ th=กำลังล้อสูงสุดของคันโยก 10–100|en=top wheel power for the sticks, 10–100|lo=ກຳລັງລໍ້ສູງສຸດຂອງຄັນໂຍກ 10–100'),
    '};',
  ].filter(Boolean).join('\n');
}

function exportHTML(config, lang) {
  if (!TEXT[lang]) lang = 'th';
  const c = normalize(config || {}, lang);
  const dirs = c.mode === 'tap4' || c.mode === 'hold4', sticks = c.mode === 'stick1' || c.mode === 'stick2';
  const extra = c.buttons.length > 0;
  const html = sections(localize(TEMPLATE, lang, escHTML));
  const css = sections(localize(CSS, lang, (s) => s));
  const want = { base: true, round: dirs || extra, dirs, stick: sticks, xbtn: extra, term: c.terminal };
  const style = Object.keys(css).filter((k) => want[k]).map((k) => css[k].trim()).join('\n');
  const parts = ['link_' + c.link, 'core', dirs && 'mode_buttons', sticks && 'mode_stick', extra && 'extra_buttons', c.terminal && 'terminal'];
  const code = parts.filter(Boolean).map((p) => localize(PARTS[p], lang, escJS).trim());
  const js = [configJS(c, dirs, sticks, lang), ...code].join('\n\n');
  const list = c.buttons.map((b) => fill(html.xbtn, {
    x: b.x, y: b.y, angle: b.angle, press: escHTML(b.press), release: escHTML(b.release), label: escHTML(b.label),
  })).join('');
  const pad = c.mode === 'none' && !extra ? '' : fill(html.pad, {
    x: extra ? ' class="x"' : '',
    ctl: dirs ? html.dirs : sticks ? html[c.mode] : '',
    xbtns: extra ? fill(html.xbtns, { list }) : '',
  });
  return fill(html.page, { lang, name: escHTML(c.name), css: style, pad, term: c.terminal ? html.term : '', js });
}

function preset(key) {
  return PRESETS[key] ? JSON.parse(JSON.stringify(PRESETS[key])) : null;
}
window.RC = { exportHTML, preset, presets: PRESETS, BROKER };
})();
